2213	110	1348971009411256320	/**\n * 游戏主逻辑实现\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <windows.h>\n#include <conio.h>\n#include "game.h"\n#include "graphics.h"\n#include "physics.h"\n#include "obstacles.h"\n\n// 游戏状态\nstatic GameState gameState;\nstatic int score;\nstatic int highScore = 0;\nstatic Bird bird;\nstatic ObstacleArray obstacles;\n\n// 初始化游戏\nvoid initGame() {\n    // 初始化游戏状态\n    gameState = GAME_START;\n    score = 0;\n    \n    // 初始化小鸟\n    bird.x = 20;\n    bird.y = GAME_HEIGHT / 2;\n    bird.velocity = 0;\n    \n    // 初始化障碍物\n    initObstacles(&obstacles);\n    \n    // 初始化图形系统\n    initGraphics();\n}\n\n// 游戏主循环\nvoid runGame() {\n    while (1) {\n        // 处理用户输入\n        handleInput();\n        \n        // 更新游戏状态\n        updateGame();\n        \n        // 渲染游戏画面\n        renderGame();\n        \n        // 控制游戏帧率\n        Sleep(FRAME_DELAY);\n    }\n}\n\n// 处理用户输入\nvoid handleInput() {\n    if (_kbhit()) {\n        char key = _getch();\n        \n        switch (gameState) {\n            case GAME_START:\n                if (key == ' ') {\n                    gameState = GAME_RUNNING;\n                }\n                break;\n                \n            case GAME_RUNNING:\n                if (key == ' ') {\n                    birdJump(&bird);\n                } else if (key == 27) { // ESC键\n                    gameState = GAME_OVER;\n                }\n                break;\n                \n            case GAME_OVER:\n                if (key == ' ') {\n                    // 重新开始游戏\n                    initGame();\n                    gameState = GAME_RUNNING;\n                } else if (key == 27) { // ESC键\n                    exit(0);\n                }\n                break;\n        }\n    }\n}\n\n// 更新游戏状态\nvoid updateGame() {\n    if (gameState != GAME_RUNNING) {\n        return;\n    }\n    \n    // 更新小鸟位置\n    updateBirdPhysics(&bird);\n    \n    // 更新障碍物位置\n    updateObstacles(&obstacles);\n    \n    // 检查碰撞\n    if (checkCollision(&bird, &obstacles)) {\n        gameOver();\n        return;\n    }\n    \n    // 检查是否通过障碍物\n    int passedObstacle = checkObstaclePassed(&bird, &obstacles);\n    if (passedObstacle) {\n        score += passedObstacle;\n    }\n    \n    // 检查是否超出边界\n    if (bird.y <= 0 || bird.y >= GAME_HEIGHT) {\n        gameOver();\n    }\n}\n\n// 渲染游戏画面\nvoid renderGame() {\n    clearScreen();\n    \n    switch (gameState) {\n        case GAME_START:\n            drawStartScreen();\n            break;\n            \n        case GAME_RUNNING:\n            drawBird(&bird);\n            drawObstacles(&obstacles);\n            drawScore(score);\n            break;\n            \n        case GAME_OVER:\n            drawGameOverScreen(score, highScore);\n            break;\n    }\n    \n    // 刷新屏幕\n    refreshScreen();\n}\n\n// 游戏结束处理\nvoid gameOver() {\n    gameState = GAME_OVER;\n    \n    // 更新最高分\n    if (score > highScore) {\n        highScore = score;\n    }\n    \n    // 播放游戏结束音效 (可选)\n    Beep(500, 200);\n    Beep(400, 300);\n}	\N	1	40.00	1	2025-04-11 01:23:37	2025-04-11 01:26:01	T10005	2025-04-11 01:23:37	23t	2025-04-11 01:31:29	f	23t	\N	\N	\N	\N	\N	\N
